                        queue.append((ny, nx))
            result.append((color, cells))
    return result


def _encloses_hole(cells):
    """True if the object encloses at least one background cell in its box."""
    min_r = min(r for r, _ in cells)
    max_r = max(r for r, _ in cells)
    min_c = min(c for _, c in cells)
    max_c = max(c for _, c in cells)
    wall = {(r, c) for r, c in cells}
    seen = set()
    q = deque()
    for r in range(min_r, max_r + 1):
        for c in (min_c, max_c):
            if (r, c) not in wall and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    for c in range(min_c, max_c + 1):
        for r in (min_r, max_r):
            if (r, c) not in wall and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if min_r <= nr <= max_r and min_c <= nc <= max_c and (nr, nc) not in wall and (nr, nc) not in seen:
                seen.add((nr, nc)); q.append((nr, nc))
    area = (max_r - min_r + 1) * (max_c - min_c + 1)
    return area > len(wall) + len(seen)


def transform(grid):
    """Closed outline objects rise to the top; open objects fall to the bottom.

    Objects retain shape, color, and columns. If same-direction objects would
    overlap at an edge, they stack while preserving their relative order.
