    h, w = len(grid), len(grid[0])
    objects = _components(grid)
    top = []
    bottom = []
    for color, cells in objects:
        item = (color, cells)
        (top if _encloses_hole(cells) else bottom).append(item)

    out = [[0] * w for _ in range(h)]

    def place_toward_edge(items, is_top):
        if is_top:
            items.sort(key=lambda item: min(r for r, _ in item[1]))
        else:
